620  /*
   621   * _libssh2_packet_add
   622   *
   623   * Create a new packet and attach it to the brigade. Called from the transport
   624   * layer when it has received a packet.
   625   *
   626   * The input pointer 'data' is pointing to allocated data that this function
   627   * will be freed unless return the code is LIBSSH2_ERROR_EAGAIN.
   628   *
   629   * This function will always be called with 'datalen' greater than zero.
   630   */
   631  int
   632  _libssh2_packet_add(LIBSSH2_SESSION * session, unsigned char *data,
   633                      size_t datalen, int macstate, uint32_t seq)
   634  {
   635      int rc = 0;
   636      unsigned char *message = NULL;
   637      unsigned char *language = NULL;
   638      size_t message_len = 0;
   639      size_t language_len = 0;
   640      LIBSSH2_CHANNEL *channelp = NULL;
   641      size_t data_head = 0;
   642      unsigned char msg = data[0];
   643
   644      switch(session->packAdd_state) {
   645      case libssh2_NB_state_idle:
   646          _libssh2_debug((session, LIBSSH2_TRACE_TRANS,
   647                         "Packet type %u received, length=%ld",
   648                         (unsigned int) msg, (long) datalen));
   649
   650          if((macstate == LIBSSH2_MAC_INVALID) &&
   651              (!session->macerror ||
   652               LIBSSH2_MACERROR(session, (char *) data, datalen))) {
   653              /* Bad MAC input, but no callback set or non-zero return from the
   654                 callback */
   655
   656              LIBSSH2_FREE(session, data);
   657              return _libssh2_error(session, LIBSSH2_ERROR_INVALID_MAC,
   658                                    "Invalid MAC received");
   659          }
   660          session->packAdd_state = libssh2_NB_state_allocated;
   661          break;
   662      case libssh2_NB_state_jump1:
   663          goto libssh2_packet_add_jump_point1;
   664      case libssh2_NB_state_jump2:
   665          goto libssh2_packet_add_jump_point2;
   666      case libssh2_NB_state_jump3:
   667          goto libssh2_packet_add_jump_point3;
   668      case libssh2_NB_state_jump4:
   669          goto libssh2_packet_add_jump_point4;
   670      case libssh2_NB_state_jump5:
   671          goto libssh2_packet_add_jump_point5;
   672      case libssh2_NB_state_jumpauthagent:
   673          goto libssh2_packet_add_jump_authagent;
   674      default: /* nothing to do */
   675          break;
   676      }
   677
   678      if(session->state & LIBSSH2_STATE_INITIAL_KEX) {
   679          if(msg == SSH_MSG_KEXINIT) {
   680              if(!session->kex_strict) {
   681                  if(datalen < 17) {
   682                      LIBSSH2_FREE(session, data);
   683                      session->packAdd_state = libssh2_NB_state_idle;
   684                      return _libssh2_error(session,
   685                                            LIBSSH2_ERROR_BUFFER_TOO_SMALL,
   686                                            "Data too short extracting kex");
   687                  }
   688                  else {
   689                      const unsigned char *strict =
   690                      (unsigned char *)"kex-strict-s-v00@openssh.com";
   691                      struct string_buf buf;
   692                      unsigned char *algs = NULL;
   693                      size_t algs_len = 0;
   694
   695                      buf.data = (unsigned char *)data;
   696                      buf.dataptr = buf.data;
   697                      buf.len = datalen;
   698                      buf.dataptr += 17; /* advance past type and cookie */
   699
   700                      if(_libssh2_get_string(&buf, &algs, &algs_len)) {
   701                          LIBSSH2_FREE(session, data);
   702                          session->packAdd_state = libssh2_NB_state_idle;
   703                          return _libssh2_error(session,
   704                                                LIBSSH2_ERROR_BUFFER_TOO_SMALL,
   705                                                "Algs too short");
   706                      }
   707
   708                      if(algs_len == 0 ||
   709                         _libssh2_kex_agree_instr(algs, algs_len, strict, 28)) {
   710                          session->kex_strict = 1;
   711                      }
   712                  }
   713              }
   714
   715              if(session->kex_strict && seq) {
   716                  LIBSSH2_FREE(session, data);
   717                  session->socket_state = LIBSSH2_SOCKET_DISCONNECTED;
   718                  session->packAdd_state = libssh2_NB_state_idle;
   719                  libssh2_session_disconnect(session, "strict KEX violation: "
   720                                             "KEXINIT was not the first packet");
   721
   722                  return _libssh2_error(session, LIBSSH2_ERROR_SOCKET_DISCONNECT,
   723                                        "strict KEX violation: "
   724                                        "KEXINIT was not the first packet");
   725              }
   726          }
   727
   728          if(session->kex_strict && session->fullpacket_required_type &&
   729              session->fullpacket_required_type != msg) {
   730              LIBSSH2_FREE(session, data);
   731              session->socket_state = LIBSSH2_SOCKET_DISCONNECTED;
   732              session->packAdd_state = libssh2_NB_state_idle;
   733              libssh2_session_disconnect(session, "strict KEX violation: "
   734                                         "unexpected packet type");
   735
   736              return _libssh2_error(session, LIBSSH2_ERROR_SOCKET_DISCONNECT,
   737                                    "strict KEX violation: "
   738                                    "unexpected packet type");
   739          }
   740      }
   741
   742      if(session->packAdd_state == libssh2_NB_state_allocated) {
   743          /* A couple exceptions to the packet adding rule: */
   744          switch(msg) {
   745
   746              /*
   747                byte      SSH_MSG_DISCONNECT
   748                uint32    reason code
   749                string    description in ISO-10646 UTF-8 encoding [RFC3629]
   750                string    language tag [RFC3066]
   751              */
   752
   753          case SSH_MSG_DISCONNECT:
   754              if(datalen >= 5) {
   755                  uint32_t reason = 0;
   756                  struct string_buf buf;
   757                  buf.data = (unsigned char *)data;
   758                  buf.dataptr = buf.data;
   759                  buf.len = datalen;
   760                  buf.dataptr++; /* advance past type */
   761
   762                  _libssh2_get_u32(&buf, &reason);
   763                  _libssh2_get_string(&buf, &message, &message_len);
   764                  _libssh2_get_string(&buf, &language, &language_len);
   765
   766                  if(session->ssh_msg_disconnect) {
   767                      LIBSSH2_DISCONNECT(session, reason, (const char *)message,
   768                                         message_len, (const char *)language,
   769                                         language_len);
   770                  }
   771
   772                  _libssh2_debug((session, LIBSSH2_TRACE_TRANS,
   773                                 "Disconnect(%d): %s(%s)", reason,
   774                                 message, language));
   775              }
   776
   777              LIBSSH2_FREE(session, data);
   778              session->socket_state = LIBSSH2_SOCKET_DISCONNECTED;
   779              session->packAdd_state = libssh2_NB_state_idle;
   780              return _libssh2_error(session, LIBSSH2_ERROR_SOCKET_DISCONNECT,
   781                                    "socket disconnect");
   782              /*
   783                byte      SSH_MSG_IGNORE
   784                string    data
   785              */
   786
   787          case SSH_MSG_IGNORE:
   788              if(datalen >= 2) {
   789                  if(session->ssh_msg_ignore) {
   790                      LIBSSH2_IGNORE(session, (char *) data + 1, datalen - 1);
   791                  }
   792              }
   793              else if(session->ssh_msg_ignore) {
   794                  LIBSSH2_IGNORE(session, "", 0);
   795              }
   796              LIBSSH2_FREE(session, data);
   797              session->packAdd_state = libssh2_NB_state_idle;
   798              return 0;
   799
   800              /*
   801                byte      SSH_MSG_DEBUG
   802                boolean   always_display
   803                string    message in ISO-10646 UTF-8 encoding [RFC3629]
   804                string    language tag [RFC3066]
   805              */
   806
   807          case SSH_MSG_DEBUG:
   808              if(datalen >= 2) {
   809                  int always_display = data[1];
   810
   811                  if(datalen >= 6) {
   812                      struct string_buf buf;
   813                      buf.data = (unsigned char *)data;
   814                      buf.dataptr = buf.data;
   815                      buf.len = datalen;
   816                      buf.dataptr += 2; /* advance past type & always display */
   817
   818                      _libssh2_get_string(&buf, &message, &message_len);
   819                      _libssh2_get_string(&buf, &language, &language_len);
   820                  }
   821
   822                  if(session->ssh_msg_debug) {
   823                      LIBSSH2_DEBUG(session, always_display,
   824                                    (const char *)message,
   825                                    message_len, (const char *)language,
   826                                    language_len);
   827                  }
   828              }
   829
   830              /*
   831               * _libssh2_debug() will actually truncate this for us so
   832               * that it's not an inordinate about of data
   833               */
   834              _libssh2_debug((session, LIBSSH2_TRACE_TRANS,
   835                             "Debug Packet: %s", message));
   836              LIBSSH2_FREE(session, data);
   837              session->packAdd_state = libssh2_NB_state_idle;
   838              return 0;
   839
   840              /*
   841                byte      SSH_MSG_EXT_INFO
   842                uint32    nr-extensions
   843                [repeat   "nr-extensions" times]
   844                string    extension-name  [RFC8308]
   845                string    extension-value (binary)
   846              */
   847
   848          case SSH_MSG_EXT_INFO:
   849              if(datalen >= 5) {
   850                  uint32_t nr_extensions = 0;
   851                  struct string_buf buf;
   852                  buf.data = (unsigned char *)data;
   853                  buf.dataptr = buf.data;
   854                  buf.len = datalen;
   855                  buf.dataptr += 1; /* advance past type */
   856
   857                  if(_libssh2_get_u32(&buf, &nr_extensions) != 0) {
   858                      rc = _libssh2_error(session, LIBSSH2_ERROR_PROTO,
   859                                          "Invalid extension info received");
   860                  }
   861
   862                  while(rc == 0 && nr_extensions > 0) {
   863
   864                      size_t name_len = 0;
   865                      size_t value_len = 0;
   866                      unsigned char *name = NULL;
   867                      unsigned char *value = NULL;
   868
   869                      nr_extensions -= 1;
   870
   871                      _libssh2_get_string(&buf, &name, &name_len);
   872                      _libssh2_get_string(&buf, &value, &value_len);
   873
   874                      if(name && value) {
   875                          _libssh2_debug((session,
   876                                         LIBSSH2_TRACE_KEX,
   877                                         "Server to Client extension %.*s: %.*s",
   878                                         (int)name_len, name,
   879                                         (int)value_len, value));
   880                      }
   881
   882                      if(name_len == 15 &&
   883                          memcmp(name, "server-sig-algs", 15) == 0) {
   884                          if(session->server_sign_algorithms) {
   885                              LIBSSH2_FREE(session,
   886                                           session->server_sign_algorithms);
   887                          }
   888
   889                          session->server_sign_algorithms =
   890                                                  LIBSSH2_ALLOC(session,
   891                                                                value_len + 1);
   892
   893                          if(session->server_sign_algorithms) {
   894                              memcpy(session->server_sign_algorithms,
   895                                     value, value_len);
   896                              session->server_sign_algorithms[value_len] = '\0';
   897                          }
   898                          else {
   899                              rc = _libssh2_error(session, LIBSSH2_ERROR_ALLOC,
   900                                                  "memory for server sign algo");
   901                          }
   902                      }
   903                  }
   904              }
   905
   906              LIBSSH2_FREE(session, data);
   907              session->packAdd_state = libssh2_NB_state_idle;
   908              return rc;
   909
   910              /*
   911                byte      SSH_MSG_GLOBAL_REQUEST
   912                string    request name in US-ASCII only
   913                boolean   want reply
   914                ....      request-specific data follows
   915              */
   916
   917          case SSH_MSG_GLOBAL_REQUEST:
   918              if(datalen >= 5) {
   919                  uint32_t len = 0;
   920                  unsigned char want_reply = 0;
   920                  unsigned char want_reply = 0;
   921                  len = _libssh2_ntohu32(data + 1);
   922                  if((len <= (UINT_MAX - 6)) && (datalen >= (6 + len))) {
   923                      want_reply = data[5 + len];
   924                      _libssh2_debug((session,
   925                                     LIBSSH2_TRACE_CONN,
   926                                     "Received global request type %.*s (wr %X)",
   927                                     (int)len, data + 5, want_reply));
   928                  }
   929
   930
   931                  if(want_reply) {
   932                      static const unsigned char packet =
   933                          SSH_MSG_REQUEST_FAILURE;
   934  libssh2_packet_add_jump_point5:
   935                      session->packAdd_state = libssh2_NB_state_jump5;
   936                      rc = _libssh2_transport_send(session, &packet, 1, NULL, 0);
   937                      if(rc == LIBSSH2_ERROR_EAGAIN)
   938                          return rc;
   939                  }
   940              }
   941              LIBSSH2_FREE(session, data);
   942              session->packAdd_state = libssh2_NB_state_idle;
   943              return 0;
   944
   945              /*
   946                byte      SSH_MSG_CHANNEL_EXTENDED_DATA
   947                uint32    recipient channel
   948                uint32    data_type_code
   949                string    data
   950              */
   951
   952          case SSH_MSG_CHANNEL_EXTENDED_DATA:
   953              /* streamid(4) */
   954              data_head += 4;
   955
   956              LIBSSH2_FALLTHROUGH();
   957
   958              /*
   959                byte      SSH_MSG_CHANNEL_DATA
   960                uint32    recipient channel
   961                string    data
   962              */
   963
   964          case SSH_MSG_CHANNEL_DATA:
   965              /* packet_type(1) + channelno(4) + datalen(4) */
   966              data_head += 9;
   967
   968              if(datalen >= data_head)
   969                  channelp =
   970                      _libssh2_channel_locate(session,
   971                                              _libssh2_ntohu32(data + 1));
   972
   973              if(!channelp) {
   974                  _libssh2_error(session, LIBSSH2_ERROR_CHANNEL_UNKNOWN,
   975                                 "Packet received for unknown channel");
   976                  LIBSSH2_FREE(session, data);
   977                  session->packAdd_state = libssh2_NB_state_idle;
   978                  return 0;
   979              }
   980  #ifdef LIBSSH2DEBUG
   981              {
   982                  uint32_t stream_id = 0;
   983                  if(msg == SSH_MSG_CHANNEL_EXTENDED_DATA)
   984                      stream_id = _libssh2_ntohu32(data + 5);
   985
   986                  _libssh2_debug((session, LIBSSH2_TRACE_CONN,
   987                                 "%ld bytes packet_add() for %u/%u/%u",
   988                                 (long) (datalen - data_head),
   989                                 channelp->local.id,
   990                                 channelp->remote.id,
   991                                 stream_id));
   992              }
   993  #endif
   994              if((channelp->remote.extended_data_ignore_mode ==
   995                   LIBSSH2_CHANNEL_EXTENDED_DATA_IGNORE) &&
   996                  (msg == SSH_MSG_CHANNEL_EXTENDED_DATA)) {
   997                  /* Pretend we didn't receive this */
   998                  LIBSSH2_FREE(session, data);
   999
  1000                  _libssh2_debug((session, LIBSSH2_TRACE_CONN,
  1001                                "Ignoring extended data and refunding %ld bytes",
  1002                                 (long) (datalen - 13)));
  1003                  if(channelp->read_avail + datalen - data_head >=
  1004                      channelp->remote.window_size)
  1005                      datalen = channelp->remote.window_size -
  1006                          channelp->read_avail + data_head;
  1007
  1008                  channelp->remote.window_size -= (uint32_t)(datalen -
  1009                                                             data_head);
  1010                  _libssh2_debug((session, LIBSSH2_TRACE_CONN,
  1011                                 "shrinking window size by %ld bytes to %u, "
  1012                                 "read_avail %ld",
  1013                                 (long) (datalen - data_head),
  1014                                 channelp->remote.window_size,
  1015                                 (long) channelp->read_avail));
  1016
  1017                  session->packAdd_channelp = channelp;
  1018
  1019                  /* Adjust the window based on the block we just freed */
  1020  libssh2_packet_add_jump_point1:
  1021                  session->packAdd_state = libssh2_NB_state_jump1;
  1022                  rc = _libssh2_channel_receive_window_adjust(session->
  1023                                                              packAdd_channelp,
  1024                                                      (uint32_t)(datalen - 13),
  1025                                                              1, NULL);
  1026                  if(rc == LIBSSH2_ERROR_EAGAIN)
  1027                      return rc;
  1028
  1029                  session->packAdd_state = libssh2_NB_state_idle;
  1030                  return 0;
  1031              }
  1032
  1033              /*
  1034               * REMEMBER! remote means remote as source of data,
  1035               * NOT remote window!
  1036               */
  1037              if(channelp->remote.packet_size < (datalen - data_head)) {
  1038                  /*
  1039                   * Spec says we MAY ignore bytes sent beyond
  1040                   * packet_size
  1041                   */
  1042                  _libssh2_error(session, LIBSSH2_ERROR_CHANNEL_PACKET_EXCEEDED,
  1043                                 "Packet contains more data than we offered"
  1044                                 " to receive, truncating");
  1045                  datalen = channelp->remote.packet_size + data_head;
  1046              }
  1047              if(channelp->remote.window_size <= channelp->read_avail) {
  1048                  /*
  1049                   * Spec says we MAY ignore bytes sent beyond
  1050                   * window_size
  1051                   */
  1052                  _libssh2_error(session, LIBSSH2_ERROR_CHANNEL_WINDOW_EXCEEDED,
  1053                                 "The current receive window is full,"
  1054                                 " data ignored");
  1055                  LIBSSH2_FREE(session, data);
  1056                  session->packAdd_state = libssh2_NB_state_idle;
  1057                  return 0;
  1058              }
  1059              /* Reset EOF status */
  1060              channelp->remote.eof = 0;
  1061
  1062              if(channelp->read_avail + datalen - data_head >
  1063                  channelp->remote.window_size) {
  1064                  _libssh2_error(session, LIBSSH2_ERROR_CHANNEL_WINDOW_EXCEEDED,
  1065                                 "Remote sent more data than current "
  1066                                 "window allows, truncating");
  1067                  datalen = channelp->remote.window_size -
  1068                      channelp->read_avail + data_head;
  1069              }
  1070
  1071              /* Update the read_avail counter. The window size will be
  1072               * updated once the data is actually read from the queue
  1073               * from an upper layer */
  1074              channelp->read_avail += datalen - data_head;
  1075
  1076              _libssh2_debug((session, LIBSSH2_TRACE_CONN,
  1077                             "increasing read_avail by %ld bytes to %ld/%u",
  1078                             (long)(datalen - data_head),
  1079                             (long)channelp->read_avail,
  1080                             channelp->remote.window_size));
  1081
  1082              break;
  1083
  1084              /*
  1085                byte      SSH_MSG_CHANNEL_EOF
  1086                uint32    recipient channel
  1087              */
  1088
  1089          case SSH_MSG_CHANNEL_EOF:
  1090              if(datalen >= 5)
  1091                  channelp =
  1092                      _libssh2_channel_locate(session,
  1093                                              _libssh2_ntohu32(data + 1));
  1094              if(!channelp)
  1095                  /* We may have freed already, just quietly ignore this... */
  1096                  ;
  1097              else {
  1098                  _libssh2_debug((session,
  1099                                 LIBSSH2_TRACE_CONN,
  1100                                 "EOF received for channel %u/%u",
  1101                                 channelp->local.id,
  1102                                 channelp->remote.id));
  1103                  channelp->remote.eof = 1;
  1104              }
  1105              LIBSSH2_FREE(session, data);
  1106              session->packAdd_state = libssh2_NB_state_idle;
  1107              return 0;
  1108
  1109              /*
  1110                byte      SSH_MSG_CHANNEL_REQUEST
  1111                uint32    recipient channel
  1112                string    request type in US-ASCII characters only
  1113                boolean   want reply
  1114                ....      type-specific data follows
  1115              */
  1116
  1117          case SSH_MSG_CHANNEL_REQUEST:
  1118              if(datalen >= 9) {
  1119                  uint32_t channel = _libssh2_ntohu32(data + 1);
  1120                  uint32_t len = _libssh2_ntohu32(data + 5);
  1121                  unsigned char want_reply = 1;
  1122
  1123                  if((len + 9) < datalen)
  1124                      want_reply = data[len + 9];
  1125
  1126                  _libssh2_debug((session,
  1127                                 LIBSSH2_TRACE_CONN,
  1128                                 "Channel %u received request type %.*s (wr %X)",
  1129                                 channel, (int)len, data + 9, want_reply));
  1130
  1131                  if(len == strlen("exit-status")
  1132                      && (strlen("exit-status") + 9) <= datalen
  1133                      && !memcmp("exit-status", data + 9,
  1134                                 strlen("exit-status"))) {
  1135
  1136                      /* we've got "exit-status" packet. Set the session value */
  1137                      if(datalen >= 20)
  1138                          channelp =
  1139                              _libssh2_channel_locate(session, channel);
  1140
  1141                      if(channelp && (strlen("exit-status") + 14) <= datalen) {
  1142                          channelp->exit_status =
  1143                              _libssh2_ntohu32(data + 10 +
  1144                                               strlen("exit-status"));
  1145                          _libssh2_debug((session, LIBSSH2_TRACE_CONN,
  1146                                         "Exit status %d received for "
  1147                                         "channel %u/%u",
  1148                                         channelp->exit_status,
  1149                                         channelp->local.id,
  1150                                         channelp->remote.id));
  1151                      }
  1152
  1153                  }
  1154                  else if(len == strlen("exit-signal")
  1155                           && (strlen("exit-signal") + 9) <= datalen
  1156                           && !memcmp("exit-signal", data + 9,
  1157                                      strlen("exit-signal"))) {
  1158                      /* command terminated due to signal */
  1159                      if(datalen >= 20)
  1160                          channelp = _libssh2_channel_locate(session, channel);
